import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

export const SPACING = 1;
export const QUARTER = Math.PI / 2;

const CUBIE_SIZE = 0.96;
const STICKER_SIZE = 0.84;
const STICKER_RADIUS = 0.11;

// Face order: +X (R), -X (L), +Y (U), -Y (D), +Z (F), -Z (B), standard Western colour scheme.
export const FACE_COLORS = ['#c41e3a', '#ff6a13', '#f4f4f4', '#ffd500', '#009e60', '#0051ba'];

export const AXES = [new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 1)];

const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const easeOut = (t) => 1 - Math.pow(1 - t, 3);

const _q = new THREE.Quaternion();
const _m = new THREE.Matrix4();
const _v = new THREE.Vector3();
const _z = new THREE.Vector3(0, 0, 1);

/** Wraps a quarter-turn count into -1, 0, 1 or 2. */
export function normalizeTurns(turns) {
  const t = ((turns % 4) + 4) % 4;
  return t === 3 ? -1 : t;
}

/**
 * A move is { axis: 0|1|2, layers: number[], turns }, where layers are indices 0..size-1
 * along the axis and positive turns rotate counter-clockwise about the positive axis.
 */
export function invertMove(move) {
  return { axis: move.axis, layers: [...move.layers], turns: normalizeTurns(-move.turns) };
}

function faceKey(v) {
  let axis = 0;
  for (let a = 1; a < 3; a++) if (Math.abs(v.getComponent(a)) > Math.abs(v.getComponent(axis))) axis = a;
  return axis * 2 + (v.getComponent(axis) > 0 ? 0 : 1);
}

function createStickerGeometry() {
  const s = STICKER_SIZE / 2;
  const r = STICKER_RADIUS;
  const shape = new THREE.Shape();
  shape.moveTo(-s + r, -s);
  shape.lineTo(s - r, -s);
  shape.absarc(s - r, -s + r, r, -Math.PI / 2, 0, false);
  shape.lineTo(s, s - r);
  shape.absarc(s - r, s - r, r, 0, Math.PI / 2, false);
  shape.lineTo(-s + r, s);
  shape.absarc(-s + r, s - r, r, Math.PI / 2, Math.PI, false);
  shape.lineTo(-s, -s + r);
  shape.absarc(-s + r, -s + r, r, Math.PI, Math.PI * 1.5, false);

  const bevel = 0.006;
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: 0.006,
    bevelEnabled: true,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelSegments: 2,
    curveSegments: 6,
  });
  // Put the underside of the sticker at z = 0.
  geometry.translate(0, 0, bevel);
  return geometry;
}

export class RubiksCube {
  constructor() {
    this.group = new THREE.Group();
    this.size = 0;
    this.cubies = [];
    this.queue = [];
    this.turn = null; // layer currently detached from the grid (animating or being dragged)
    this.anim = null;
    this.turnDuration = 190;
    this.onIdle = null;

    this.bodyGeometry = new RoundedBoxGeometry(CUBIE_SIZE, CUBIE_SIZE, CUBIE_SIZE, 3, 0.08);
    this.bodyMaterial = new THREE.MeshStandardMaterial({ color: 0x111114, roughness: 0.45, metalness: 0.05 });
    this.stickerGeometry = createStickerGeometry();
    this.stickerMaterials = FACE_COLORS.map(
      (color) =>
        new THREE.MeshPhysicalMaterial({ color, roughness: 0.3, clearcoat: 0.6, clearcoatRoughness: 0.2 }),
    );
  }

  get busy() {
    return this.turn !== null || this.queue.length > 0;
  }

  build(size) {
    this.queue.length = 0;
    this.anim = null;
    this.turn = null;
    for (const cubie of this.cubies) this.group.remove(cubie);
    this.cubies = [];
    this.size = size;

    const half = (size - 1) / 2;
    for (let x = 0; x < size; x++) {
      for (let y = 0; y < size; y++) {
        for (let z = 0; z < size; z++) {
          const coord = [x, y, z];
          if (!coord.some((c) => c === 0 || c === size - 1)) continue; // hidden core

          const cubie = new THREE.Group();
          cubie.add(new THREE.Mesh(this.bodyGeometry, this.bodyMaterial));

          const stickers = [];
          for (let axis = 0; axis < 3; axis++) {
            for (const sign of [1, -1]) {
              if (coord[axis] !== (sign > 0 ? size - 1 : 0)) continue;
              const face = axis * 2 + (sign > 0 ? 0 : 1);
              const normal = AXES[axis].clone().multiplyScalar(sign);
              const sticker = new THREE.Mesh(this.stickerGeometry, this.stickerMaterials[face]);
              sticker.quaternion.setFromUnitVectors(_z, normal);
              sticker.position.copy(normal).multiplyScalar(CUBIE_SIZE / 2 - 0.002);
              sticker.userData = { face, normal };
              cubie.add(sticker);
              stickers.push(sticker);
            }
          }

          cubie.position.set((x - half) * SPACING, (y - half) * SPACING, (z - half) * SPACING);
          cubie.userData = {
            coord,
            stickers,
            basePosition: new THREE.Vector3(),
            baseQuaternion: new THREE.Quaternion(),
          };
          this.group.add(cubie);
          this.cubies.push(cubie);
        }
      }
    }
  }

  /** Queues an animated move. `duration` (ms) overrides the default speed. */
  enqueue(move, duration) {
    this.queue.push({ move, duration });
  }

  /** Detaches a set of layers so they can be rotated freely. */
  beginTurn(axis, layers) {
    const cubies = this.cubies.filter((c) => layers.includes(c.userData.coord[axis]));
    for (const c of cubies) {
      c.userData.basePosition.copy(c.position);
      c.userData.baseQuaternion.copy(c.quaternion);
    }
    this.turn = { axis, layers, cubies, angle: 0 };
  }

  setTurnAngle(angle) {
    const turn = this.turn;
    turn.angle = angle;
    _q.setFromAxisAngle(AXES[turn.axis], angle);
    for (const c of turn.cubies) {
      c.position.copy(c.userData.basePosition).applyQuaternion(_q);
      c.quaternion.copy(_q).multiply(c.userData.baseQuaternion);
    }
  }

  /** Animates the detached layer from wherever it is to the nearest whole number of quarter turns. */
  settleTurn(turns) {
    const from = this.turn.angle;
    const to = turns * QUARTER;
    const duration = 70 + Math.min(1.5, Math.abs(to - from) / QUARTER) * 150;
    this.anim = { from, to, turns, start: performance.now(), duration, ease: easeOut };
  }

  endTurn(turns) {
    this.setTurnAngle(turns * QUARTER);
    for (const c of this.turn.cubies) this.snap(c);
    this.turn = null;
  }

  /** Removes floating-point drift and refreshes the cubie's grid coordinates. */
  snap(cubie) {
    const half = (this.size - 1) / 2;
    for (let a = 0; a < 3; a++) {
      const i = Math.round(cubie.position.getComponent(a) / SPACING + half);
      cubie.userData.coord[a] = i;
      cubie.position.setComponent(a, (i - half) * SPACING);
    }
    _m.makeRotationFromQuaternion(cubie.quaternion);
    const e = _m.elements;
    for (let i = 0; i < 16; i++) e[i] = Math.round(e[i]);
    cubie.quaternion.setFromRotationMatrix(_m);
  }

  update(now) {
    if (this.anim) {
      const a = this.anim;
      const t = Math.min(1, Math.max(0, (now - a.start) / a.duration));
      this.setTurnAngle(a.from + (a.to - a.from) * a.ease(t));
      if (t < 1) return;
      this.anim = null;
      this.endTurn(a.turns);
      if (this.queue.length === 0) this.onIdle?.();
    }

    if (!this.turn && this.queue.length > 0) {
      const { move, duration } = this.queue.shift();
      let ms = duration ?? this.turnDuration * (this.queue.length > 1 ? 0.6 : 1);
      if (Math.abs(move.turns) === 2) ms *= 1.4;
      this.beginTurn(move.axis, move.layers);
      this.anim = { from: 0, to: move.turns * QUARTER, turns: move.turns, start: now, duration: ms, ease: easeInOut };
    }
  }

  /** True when every face shows a single colour, regardless of whole-cube orientation. */
  isSolved() {
    const seen = [-1, -1, -1, -1, -1, -1];
    for (const cubie of this.cubies) {
      for (const sticker of cubie.userData.stickers) {
        _v.copy(sticker.userData.normal).applyQuaternion(cubie.quaternion);
        const key = faceKey(_v);
        if (seen[key] === -1) seen[key] = sticker.userData.face;
        else if (seen[key] !== sticker.userData.face) return false;
      }
    }
    return true;
  }
}

import * as THREE from 'three';
import { normalizeTurns } from './cube.js';

const SUFFIX = ['', '', '2', "'"];
const suffix = (amount) => SUFFIX[((amount % 4) + 4) % 4];

/** Formats a single-layer move in standard notation (SiGN prefixes like "2R" for inner layers). */
export function formatMove({ axis, layers, turns }, size) {
  const layer = layers[0];
  if (size === 3 && layer === 1) {
    // M follows L, E follows D, S follows F.
    return 'MES'[axis] + suffix(axis === 2 ? -turns : turns);
  }
  if (layer >= (size - 1) / 2) {
    const depth = size - layer;
    return (depth > 1 ? depth : '') + 'RUF'[axis] + suffix(-turns);
  }
  return (layer > 0 ? layer + 1 : '') + 'LDB'[axis] + suffix(turns);
}

/**
 * Random-move scramble. Middle layers of odd cubes are skipped so the centres stay put, and
 * no layer is turned twice within a run of moves on the same axis (avoids R R and R L R).
 */
export function generateScramble(size, length) {
  const middle = (size - 1) / 2;
  const layers = [...Array(size).keys()].filter((l) => l !== middle);
  const pick = (list) => list[Math.floor(Math.random() * list.length)];
  const moves = [];
  let runAxis = -1;
  let runLayers = new Set();
  while (moves.length < length) {
    const axis = Math.floor(Math.random() * 3);
    const layer = pick(layers);
    if (axis === runAxis && runLayers.has(layer)) continue;
    if (axis !== runAxis) {
      runAxis = axis;
      runLayers = new Set();
    }
    runLayers.add(layer);
    moves.push({ axis, layers: [layer], turns: pick([1, -1, 2]) });
  }
  return moves;
}

/** Collapses consecutive moves on the same layers (R R' disappears, R R becomes R2). */
export function mergeMoves(moves) {
  const out = [];
  for (const move of moves) {
    const prev = out[out.length - 1];
    if (prev && prev.axis === move.axis && prev.layers.join() === move.layers.join()) {
      const turns = normalizeTurns(prev.turns + move.turns);
      if (turns === 0) out.pop();
      else prev.turns = turns;
    } else {
      out.push({ ...move, layers: [...move.layers] });
    }
  }
  return out;
}

function dominantAxis(v, exclude = -1) {
  let axis = -1;
  for (let a = 0; a < 3; a++) {
    if (a === exclude) continue;
    if (axis === -1 || Math.abs(v.getComponent(a)) > Math.abs(v.getComponent(axis))) axis = a;
  }
  return { axis, sign: v.getComponent(axis) >= 0 ? 1 : -1 };
}

const toVector = ({ axis, sign }) => new THREE.Vector3().setComponent(axis, sign);
const opposite = ({ axis, sign }) => ({ axis, sign: -sign });

/** Works out which cube face is front / up / right from the camera's point of view. */
export function viewFrame(camera, target) {
  const F = dominantAxis(camera.position.clone().sub(target));
  const U = dominantAxis(new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion), F.axis);
  const R = dominantAxis(toVector(U).cross(toVector(F)));
  return { F, U, R, B: opposite(F), D: opposite(U), L: opposite(R) };
}

/**
 * Maps a key press to a move, relative to the current view. `depth` selects an inner layer
 * (1 = outer face) for U/D/L/R/F/B.
 */
export function keyMove(key, prime, depth, size, frame) {
  const amount = prime ? -1 : 1;
  const all = [...Array(size).keys()];
  // Clockwise when looking at the face = negative rotation about its outward normal.
  const turn = (face, layers) => ({ axis: face.axis, layers, turns: -face.sign * amount });

  if ('UDLRFB'.includes(key)) {
    const face = frame[key];
    const d = Math.min(Math.max(depth, 1), size);
    return turn(face, [face.sign > 0 ? size - d : d - 1]);
  }
  if ('MES'.includes(key)) {
    if (size < 3) return null;
    return turn(frame[{ M: 'L', E: 'D', S: 'F' }[key]], all.slice(1, -1));
  }
  if ('XYZ'.includes(key)) {
    return turn(frame[{ X: 'R', Y: 'U', Z: 'F' }[key]], all);
  }
  return null;
}

import * as THREE from 'three';
import { SPACING, QUARTER, normalizeTurns } from './cube.js';

const DRAG_THRESHOLD = 7; // px before a press becomes a layer turn
const FLICK_SPEED = 2.5; // rad/s; a quick flick completes the turn even if it was short

/**
 * Lets the user grab any sticker and drag its layer around. Presses that miss the cube fall
 * through to OrbitControls, which is disabled for the duration of a layer drag.
 */
export class DragController {
  constructor(dom, camera, cube, { onTurn, onPress } = {}) {
    this.dom = dom;
    this.camera = camera;
    this.cube = cube;
    this.controls = null;
    this.onTurn = onTurn;
    this.onPress = onPress;
    this.drag = null;
    this.raycaster = new THREE.Raycaster();
    this.ndc = new THREE.Vector2();
    this.box = new THREE.Box3();

    // Capture phase on window runs before OrbitControls' own listener on the canvas.
    window.addEventListener('pointerdown', this.onDown, { capture: true });
    window.addEventListener('pointermove', this.onMove);
    window.addEventListener('pointerup', this.onUp);
    window.addEventListener('pointercancel', this.onUp);
    window.addEventListener('blur', () => this.release());
  }

  get active() {
    return this.drag !== null;
  }

  /** Intersects the cube's bounding box; returns the hit point and the face it lies on. */
  pick(clientX, clientY) {
    const rect = this.dom.getBoundingClientRect();
    this.ndc.set(((clientX - rect.left) / rect.width) * 2 - 1, -((clientY - rect.top) / rect.height) * 2 + 1);
    this.raycaster.setFromCamera(this.ndc, this.camera);
    const h = (this.cube.size * SPACING) / 2 - 0.02;
    this.box.min.setScalar(-h);
    this.box.max.setScalar(h);
    const point = this.raycaster.ray.intersectBox(this.box, new THREE.Vector3());
    if (!point) return null;
    let axis = 0;
    for (let a = 1; a < 3; a++) if (Math.abs(point.getComponent(a)) > Math.abs(point.getComponent(axis))) axis = a;
    return { point, axis, sign: Math.sign(point.getComponent(axis)) || 1 };
  }

  toScreen(v) {
    const rect = this.dom.getBoundingClientRect();
    const p = v.clone().project(this.camera);
    return new THREE.Vector2(((p.x + 1) / 2) * rect.width, ((1 - p.y) / 2) * rect.height);
  }

  onDown = (e) => {
    if (e.target !== this.dom) return;
    this.onPress?.();
    if (this.drag || !e.isPrimary || e.button !== 0 || this.cube.busy) return;
    const hit = this.pick(e.clientX, e.clientY);
    if (!hit) return;
    if (this.controls) this.controls.enabled = false;
    this.drag = { id: e.pointerId, start: new THREE.Vector2(e.clientX, e.clientY), hit, rotating: false, samples: [] };
    this.dom.setPointerCapture?.(e.pointerId);
    this.dom.style.cursor = 'grabbing';
  };

  onMove = (e) => {
    const d = this.drag;
    if (!d) {
      if (e.target === this.dom && e.buttons === 0) {
        this.dom.style.cursor = this.pick(e.clientX, e.clientY) ? 'grab' : '';
      }
      return;
    }
    if (e.pointerId !== d.id) return;

    const delta = new THREE.Vector2(e.clientX, e.clientY).sub(d.start);
    if (!d.rotating) {
      if (delta.length() < DRAG_THRESHOLD) return;
      if (this.cube.busy) return this.release();
      this.beginRotation(d, delta);
    }

    // Distance dragged along the chosen direction, converted to world units and then to an
    // angle so the grabbed sticker roughly follows the pointer.
    const along = delta.dot(d.direction) / d.pixelsPerUnit;
    const angle = (along / d.radius) * d.sign;
    this.cube.setTurnAngle(angle);

    const now = performance.now();
    d.samples.push({ t: now, angle });
    while (d.samples.length > 2 && d.samples[0].t < now - 120) d.samples.shift();
  };

  /** Chooses which layer to turn from the face that was grabbed and the initial drag direction. */
  beginRotation(d, delta) {
    const { point, axis: normalAxis, sign: normalSign } = d.hit;
    const origin = this.toScreen(point);

    // Of the two in-plane axes of the grabbed face, pick the one whose on-screen direction best
    // matches the drag.
    let best = null;
    for (let a = 0; a < 3; a++) {
      if (a === normalAxis) continue;
      const moved = point.clone();
      moved.setComponent(a, moved.getComponent(a) + SPACING);
      const v = this.toScreen(moved).sub(origin);
      const length = v.length();
      if (length < 1e-6) continue;
      const alignment = Math.abs(v.dot(delta)) / length;
      if (!best || alignment > best.alignment) best = { axis: a, v, length, alignment };
    }

    // Turning about n × d moves the grabbed point along +d.
    const dragAxis = best.axis;
    const turnAxis = 3 - normalAxis - dragAxis;
    const cyclic = (dragAxis - normalAxis + 3) % 3 === 1;
    const half = (this.cube.size * SPACING) / 2;
    const layer = THREE.MathUtils.clamp(
      Math.floor((point.getComponent(turnAxis) + half) / SPACING),
      0,
      this.cube.size - 1,
    );

    this.cube.beginTurn(turnAxis, [layer]);
    Object.assign(d, {
      rotating: true,
      axis: turnAxis,
      layer,
      sign: normalSign * (cyclic ? 1 : -1),
      direction: best.v.clone().normalize(),
      pixelsPerUnit: best.length / SPACING,
      radius: half,
    });
  }

  onUp = (e) => {
    if (this.drag && e.pointerId === this.drag.id) this.release();
  };

  release() {
    const d = this.drag;
    if (!d) return;
    this.drag = null;
    if (this.controls) this.controls.enabled = true;
    this.dom.style.cursor = '';
    if (!d.rotating || !this.cube.turn) return;

    const angle = this.cube.turn.angle;
    const quarters = angle / QUARTER;
    let turns = Math.round(quarters);

    const now = performance.now();
    const recent = d.samples.filter((s) => s.t >= now - 120);
    if (recent.length >= 2 && Math.abs(quarters) < 1) {
      const first = recent[0];
      const last = recent[recent.length - 1];
      const velocity = (last.angle - first.angle) / Math.max(0.001, (last.t - first.t) / 1000);
      if (Math.abs(velocity) > FLICK_SPEED) {
        turns = Math.sign(velocity) === Math.sign(quarters) ? Math.sign(quarters) : 0;
      }
    }

    this.cube.settleTurn(turns);
    const normalized = normalizeTurns(turns);
    if (normalized !== 0) this.onTurn?.({ axis: d.axis, layers: [d.layer], turns: normalized });
  }
}

import * as THREE from 'three';

const LIFETIME = 3.2;
const GRAVITY = 9;

/** A burst of sticker-coloured confetti, drawn as one instanced mesh. */
export class Confetti {
  constructor(scene, colors, count = 320) {
    this.count = count;
    this.life = 0;
    this.mesh = new THREE.InstancedMesh(
      new THREE.PlaneGeometry(0.14, 0.22),
      new THREE.MeshStandardMaterial({ side: THREE.DoubleSide, roughness: 0.5 }),
      count,
    );
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.visible = false;

    const color = new THREE.Color();
    for (let i = 0; i < count; i++) this.mesh.setColorAt(i, color.set(colors[i % colors.length]));

    this.particles = Array.from({ length: count }, () => ({
      position: new THREE.Vector3(),
      velocity: new THREE.Vector3(),
      quaternion: new THREE.Quaternion(),
      spinAxis: new THREE.Vector3(),
      spin: 0,
    }));
    this.dummy = new THREE.Object3D();
    this.step = new THREE.Quaternion();
    scene.add(this.mesh);
  }

  burst(cubeSize) {
    const scale = cubeSize / 3;
    for (const p of this.particles) {
      const dir = new THREE.Vector3().randomDirection();
      dir.y = Math.abs(dir.y) * 0.8 + 0.2;
      dir.normalize();
      p.position.copy(dir).multiplyScalar(cubeSize * 0.45);
      p.velocity.copy(dir).multiplyScalar((5 + Math.random() * 6) * scale);
      p.spinAxis.randomDirection();
      p.spin = 4 + Math.random() * 10;
      p.quaternion.setFromAxisAngle(p.spinAxis, Math.random() * Math.PI * 2);
    }
    this.life = LIFETIME;
    this.mesh.visible = true;
  }

  update(dt) {
    if (!this.mesh.visible) return;
    this.life -= dt;
    if (this.life <= 0) {
      this.mesh.visible = false;
      return;
    }
    const fade = Math.min(1, this.life / 0.8);
    this.particles.forEach((p, i) => {
      p.velocity.y -= GRAVITY * dt;
      p.velocity.multiplyScalar(1 - 1.6 * dt);
      p.position.addScaledVector(p.velocity, dt);
      p.quaternion.multiply(this.step.setFromAxisAngle(p.spinAxis, p.spin * dt));
      this.dummy.position.copy(p.position);
      this.dummy.quaternion.copy(p.quaternion);
      this.dummy.scale.setScalar(fade);
      this.dummy.updateMatrix();
      this.mesh.setMatrixAt(i, this.dummy.matrix);
    });
    this.mesh.instanceMatrix.needsUpdate = true;
  }
}

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { RubiksCube, FACE_COLORS, invertMove } from './cube.js';
import { DragController } from './drag.js';
import { Confetti } from './confetti.js';
import { formatMove, generateScramble, keyMove, mergeMoves, viewFrame } from './notation.js';

const SCRAMBLE_LENGTH = { 2: 11, 3: 22, 4: 40, 5: 60 };
const SCRAMBLE_TURN_MS = 55;

const $ = (id) => document.getElementById(id);
const ui = {
  app: $('app'),
  time: $('time'),
  moves: $('moves'),
  scramble: $('scramble'),
  toast: $('toast'),
  help: $('help'),
  undo: $('btn-undo'),
  solve: $('btn-solve'),
  sizes: [...document.querySelectorAll('[data-size]')],
};

// ---------------------------------------------------------------------------------------------
// Scene

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.NeutralToneMapping;
renderer.domElement.id = 'scene';
ui.app.prepend(renderer.domElement);

const scene = new THREE.Scene();
scene.environment = new THREE.PMREMGenerator(renderer).fromScene(new RoomEnvironment(), 0.04).texture;
scene.environmentIntensity = 0.85;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.3);
keyLight.position.set(5, 9, 7);
const rimLight = new THREE.DirectionalLight(0xa8bcff, 0.5);
rimLight.position.set(-6, -4, -5);
scene.add(keyLight, rimLight);

const camera = new THREE.PerspectiveCamera(38, window.innerWidth / window.innerHeight, 0.1, 200);
camera.position.set(0.62, 0.55, 1);

const cube = new RubiksCube();
scene.add(cube.group);
const confetti = new Confetti(scene, FACE_COLORS);

// Created before OrbitControls so layer drags can claim the pointer first.
const drag = new DragController(renderer.domElement, camera, cube, {
  onTurn: (move) => recordMove(move, 'user'),
  onPress: stopIntroSpin,
});

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.enablePan = false;
controls.rotateSpeed = 0.9;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.7;
drag.controls = controls;

function fitCamera(size) {
  const radius = size * 0.5 * Math.sqrt(3);
  const vHalf = THREE.MathUtils.degToRad(camera.fov / 2);
  const hHalf = Math.atan(Math.tan(vHalf) * camera.aspect);
  const distance = (radius / Math.sin(Math.min(vHalf, hHalf))) * 1.15;
  camera.position.normalize().multiplyScalar(distance);
  controls.minDistance = radius * 1.3;
  controls.maxDistance = distance * 2.5;
  controls.update();
}

function stopIntroSpin() {
  controls.autoRotate = false;
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ---------------------------------------------------------------------------------------------
// Game state
//
// phase: idle (free play) → scrambling → ready (inspection) → solving (timer running) → idle
//        or autosolve while the Solve button rewinds the history.

const state = {
  phase: 'idle',
  history: [], // { move, kind } in the order the moves were issued
  moves: 0,
  timerStart: 0,
  elapsed: 0,
  depth: 1, // inner-layer prefix typed with the number keys
};

const isRotation = (move) => move.layers.length === cube.size;
const locked = () => drag.active || state.phase === 'scrambling' || state.phase === 'autosolve';

function recordMove(move, kind) {
  state.history.push({ move, kind });
  if (kind === 'user' && !isRotation(move)) {
    state.moves++;
    if (state.phase === 'ready') {
      state.phase = 'solving';
      state.timerStart = performance.now();
    }
  }
  refreshUI();
}

function perform(move, kind, duration) {
  cube.enqueue(move, duration);
  recordMove(move, kind);
}

function resetSession() {
  state.phase = 'idle';
  state.history = [];
  state.moves = 0;
  state.elapsed = 0;
  ui.scramble.hidden = true;
  hideToast();
  refreshUI();
}

function reset(size = cube.size) {
  if (drag.active) return;
  const resized = size !== cube.size;
  cube.build(size);
  if (resized) fitCamera(size);
  resetSession();
}

function scramble() {
  if (drag.active) return;
  cube.build(cube.size); // always scramble from solved so the listed sequence reproduces it
  resetSession();
  const moves = generateScramble(cube.size, SCRAMBLE_LENGTH[cube.size]);
  state.phase = 'scrambling';
  for (const move of moves) perform(move, 'scramble', SCRAMBLE_TURN_MS);
  ui.scramble.textContent = moves.map((m) => formatMove(m, cube.size)).join(' ');
  ui.scramble.hidden = false;
  refreshUI();
}

function undo() {
  if (locked()) return;
  const last = state.history.pop();
  if (!last) return;
  cube.enqueue(invertMove(last.move));
  if (last.kind === 'user' && !isRotation(last.move)) state.moves = Math.max(0, state.moves - 1);
  refreshUI();
}

/** Plays the whole history backwards (with trivial cancellations merged). */
function solve() {
  if (locked() || state.history.length === 0) return;
  const moves = mergeMoves(state.history.map((h) => invertMove(h.move)).reverse());
  state.history = [];
  if (state.phase === 'solving') state.elapsed = performance.now() - state.timerStart;
  ui.scramble.hidden = true;
  state.phase = moves.length > 0 ? 'autosolve' : 'idle';
  const duration = THREE.MathUtils.clamp(4500 / moves.length, 70, 180);
  for (const move of moves) cube.enqueue(move, duration);
  refreshUI();
}

cube.onIdle = () => {
  const solved = cube.isSolved();
  if (state.phase === 'scrambling') {
    state.phase = solved ? 'idle' : 'ready';
    if (!solved) showToast('Scrambled: the timer starts on your first turn');
  } else if (solved && state.phase !== 'idle') {
    if (state.phase === 'solving') {
      state.elapsed = performance.now() - state.timerStart;
      showToast(`Solved in ${formatTime(state.elapsed)} · ${state.moves} moves`, 6000);
      confetti.burst(cube.size);
    }
    state.phase = 'idle';
    ui.scramble.hidden = true;
  }
  refreshUI();
};

// ---------------------------------------------------------------------------------------------
// UI

function formatTime(ms) {
  const cs = Math.floor(Math.max(0, ms) / 10);
  const minutes = Math.floor(cs / 6000);
  const seconds = Math.floor(cs / 100) % 60;
  return `${minutes}:${String(seconds).padStart(2, '0')}.${String(cs % 100).padStart(2, '0')}`;
}

function refreshUI() {
  ui.moves.textContent = state.moves;
  if (state.phase !== 'solving') ui.time.textContent = formatTime(state.elapsed);
  ui.time.classList.toggle('running', state.phase === 'solving');
  ui.time.classList.toggle('armed', state.phase === 'ready');
  ui.undo.disabled = state.history.length === 0;
  ui.solve.disabled = state.history.length === 0;
  for (const button of ui.sizes) button.classList.toggle('active', Number(button.dataset.size) === cube.size);
}

let toastTimer = 0;
function showToast(text, ms = 3000) {
  ui.toast.textContent = text;
  ui.toast.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(hideToast, ms);
}
function hideToast() {
  ui.toast.hidden = true;
}

function toggleHelp(show = ui.help.hidden) {
  ui.help.hidden = !show;
}

function onClick(id, handler) {
  $(id).addEventListener('click', (e) => {
    e.currentTarget.blur();
    stopIntroSpin();
    handler();
  });
}
onClick('btn-scramble', scramble);
onClick('btn-undo', undo);
onClick('btn-solve', solve);
onClick('btn-reset', () => reset());
onClick('btn-help', () => toggleHelp());
onClick('btn-help-close', () => toggleHelp(false));
for (const button of ui.sizes) onClick(button.id, () => reset(Number(button.dataset.size)));

let depthTimer = 0;
window.addEventListener('keydown', (e) => {
  if (e.repeat) return;
  stopIntroSpin();

  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') {
    e.preventDefault();
    undo();
    return;
  }
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if (e.key === 'Backspace') {
    e.preventDefault();
    undo();
    return;
  }
  if (e.key === '?') return toggleHelp();
  if (e.key === 'Escape') return toggleHelp(false);

  if (/^[1-9]$/.test(e.key)) {
    state.depth = Number(e.key);
    clearTimeout(depthTimer);
    depthTimer = setTimeout(() => (state.depth = 1), 1500);
    return;
  }

  const move = keyMove(e.key.toUpperCase(), e.shiftKey, state.depth, cube.size, viewFrame(camera, controls.target));
  if (!move) return;
  e.preventDefault();
  state.depth = 1;
  if (locked()) return;
  perform(move, 'user');
});

// ---------------------------------------------------------------------------------------------
// Start

cube.build(3);
fitCamera(3);
refreshUI();

let lastFrame = performance.now();
renderer.setAnimationLoop(() => {
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastFrame) / 1000);
  lastFrame = now;

  cube.update(now);
  controls.update(dt);
  confetti.update(dt);
  if (state.phase === 'solving') ui.time.textContent = formatTime(now - state.timerStart);

  renderer.render(scene, camera);
});

