:root {
  color-scheme: dark;
  --panel: rgba(20, 24, 32, 0.72);
  --panel-border: rgba(255, 255, 255, 0.09);
  --text: #e9edf3;
  --muted: #8d96a6;
  --accent: #ffd500;
  --radius: 12px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #0a0c10;
  color: var(--text);
  -webkit-user-select: none;
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  background: radial-gradient(120% 90% at 50% 38%, #283146 0%, #151a24 55%, #0a0c10 100%);
}

#scene {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

/* ---- HUD --------------------------------------------------------------- */

.hud {
  position: absolute;
  top: max(16px, env(safe-area-inset-top));
  left: max(18px, env(safe-area-inset-left));
  pointer-events: none;
}

h1 {
  margin: 0 0 10px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.stats {
  display: flex;
  gap: 22px;
  margin: 0;
}

.stats dt {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.stats dd {
  margin: 2px 0 0;
  font-size: 26px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
