import * as THREE from 'three';
import { RubiksCube, invertMove, FACE_COLORS } from './cube.js';
import { formatMove, generateScramble, keyMove, mergeMoves, viewFrame } from './notation.js';

let fails = 0;
const check = (name, ok) => { console.log((ok ? 'PASS ' : 'FAIL ') + name); if (!ok) fails++; };

function apply(cube, move) { cube.beginTurn(move.axis, move.layers); cube.endTurn(move.turns); }
function applyAll(cube, moves) { moves.forEach((m) => apply(cube, m)); }
const faceNames = ['R', 'L', 'U', 'D', 'F', 'B'];
// Returns colour name of sticker facing `dir` on the cubie at coord
function stickerAt(cube, coord, dirKey) {
  for (const c of cube.cubies) {
    if (c.userData.coord.join() !== coord.join()) continue;
    for (const s of c.userData.stickers) {
      const n = s.userData.normal.clone().applyQuaternion(c.quaternion);
      let a = 0; for (let i = 1; i < 3; i++) if (Math.abs(n.getComponent(i)) > Math.abs(n.getComponent(a))) a = i;
      const key = a * 2 + (n.getComponent(a) > 0 ? 0 : 1);
      if (key === dirKey) return faceNames[s.userData.face];
    }
  }
}
const frame0 = { F: { axis: 2, sign: 1 }, U: { axis: 1, sign: 1 }, R: { axis: 0, sign: 1 }, B: { axis: 2, sign: -1 }, D: { axis: 1, sign: -1 }, L: { axis: 0, sign: -1 } };
const mv = (k, prime = false, size = 3, depth = 1) => keyMove(k, prime, depth, size, frame0);

// 1. R: front-right column goes up -> U face right column shows F colour.
let cube = new RubiksCube(); cube.build(3);
apply(cube, mv('R'));
check('R moves F stickers to U', stickerAt(cube, [2, 2, 1], 2) === 'F' && stickerAt(cube, [2, 2, 0], 2) === 'F');
check('R moves U stickers to B', stickerAt(cube, [2, 1, 0], 5) === 'U');
check('R leaves L alone', stickerAt(cube, [0, 2, 2], 2) === 'U');
// U: front stickers go to left
cube.build(3); apply(cube, mv('U'));
check('U moves F top row to L', stickerAt(cube, [0, 2, 1], 1) === 'F');
// F: U bottom row goes to R
cube.build(3); apply(cube, mv('F'));
check('F moves U stickers to R', stickerAt(cube, [2, 1, 2], 0) === 'U');
// L: U goes to F
cube.build(3); apply(cube, mv('L'));
check('L moves U stickers to F', stickerAt(cube, [0, 1, 2], 4) === 'U');
// D: F goes to R
cube.build(3); apply(cube, mv('D'));
check('D moves F stickers to R', stickerAt(cube, [2, 0, 1], 0) === 'F');
// B: U goes to L
cube.build(3); apply(cube, mv('B'));
check('B moves U stickers to L', stickerAt(cube, [0, 1, 0], 1) === 'U');
// M follows L, x follows R
cube.build(3); apply(cube, mv('M'));
check('M moves U centre to F', stickerAt(cube, [1, 1, 2], 4) === 'U');
cube.build(3); apply(cube, mv('X'));
check('x moves F centre to U', stickerAt(cube, [1, 2, 1], 2) === 'F');
check('x keeps cube solved', cube.isSolved());

// 2. Sexy move x6 = identity
cube.build(3);
for (let i = 0; i < 6; i++) applyAll(cube, [mv('R'), mv('U'), mv('R', true), mv('U', true)]);
check('(R U R\' U\') x6 is identity', cube.isSolved());
cube.build(3); applyAll(cube, [mv('R'), mv('U')]);
check('R U is not solved', !cube.isSolved());

// 3. Scramble + inverse for all sizes; formatting
for (const n of [2, 3, 4, 5]) {
  cube.build(n);
  const s = generateScramble(n, 40);
  applyAll(cube, s);
  const scrambled = !cube.isSolved();
  applyAll(cube, mergeMoves(s.map(invertMove).reverse()));
  const coordsOk = cube.cubies.every((c) => c.userData.coord.every((v) => v >= 0 && v < n));
  check(`${n}x${n} scramble then inverse solves (scrambled=${scrambled})`, scrambled && cube.isSolved() && coordsOk);
  console.log('   ', s.slice(0, 12).map((m) => formatMove(m, n)).join(' '));
}
// format known moves
check('format R', formatMove(mv('R'), 3) === 'R');
check("format R'", formatMove(mv('R', true), 3) === "R'");
check("format L'", formatMove(mv('L', true), 3) === "L'");
check('format F', formatMove(mv('F'), 3) === 'F');
check('format B', formatMove(mv('B'), 3) === 'B');
check('format D', formatMove(mv('D'), 3) === 'D');
check('format 2R on 4x4', formatMove(mv('R', false, 4, 2), 4) === '2R');
check("format 2L' on 5x5", formatMove(mv('L', true, 5, 2), 5) === "2L'");
check('format R2', formatMove({ ...mv('R'), turns: 2 }, 3) === 'R2');

// 4. mergeMoves
const R = mv('R'), Ri = mv('R', true), U = mv('U');
check('merge R R\' -> []', mergeMoves([R, Ri]).length === 0);
check('merge R R -> R2', (() => { const m = mergeMoves([R, R]); return m.length === 1 && Math.abs(m[0].turns) === 2; })());
check('merge U R R\' U -> U2', (() => { const m = mergeMoves([U, R, Ri, U]); return m.length === 1 && m[0].axis === 1 && Math.abs(m[0].turns) === 2; })());

// 5. viewFrame from default-ish camera and from behind
const cam = new THREE.PerspectiveCamera();
